(7279211, 1133665, 67258, '<td valign="top">An interesting photo, but I do wish you there was more contrast.</td>', 'An interesting photo, but I do wish you there was more contrast.', '2014-11-02 15:14:01.000000', NULL, 1),
(7279212, 1133015, 67258, '<td valign="top">This has the fee of a (quite understandable) heavy crop.  I do wonder if a wider shot showing a little more environment might make for a stronger photo.  Nonetheless, an impressive wildlife image.</td>', 'This has the fee of a (quite understandable) heavy crop.  I do wonder if a wider shot showing a little more environment might make for a stronger photo.  Nonetheless, an impressive wildlife image.', '2014-11-02 15:16:32.000000', NULL, 1),
