(7279971, 1134096, 30982, '<td valign="top">Looks almost like a publicity photo, yet I do not see him as the player of the instrument for some reason.  Still, a very good photo - great lighting particularly the eyes.</td>', 'Looks almost like a publicity photo, yet I do not see him as the player of the instrument for some reason.  Still, a very good photo - great lighting particularly the eyes.', '2014-11-04 23:18:17.000000', NULL, 1),
(7279973, 1131908, 30982, '<td valign="top">Gorgeous location, great sky, but seems as though there is almost too much going on all at once.  Then again, it makes the lighthouse incidental to its environment, and that is fitting.</td>', 'Gorgeous location, great sky, but seems as though there is almost too much going on all at once.  Then again, it makes the lighthouse incidental to its environment, and that is fitting.', '2014-11-04 23:19:19.000000', NULL, 1),
(7279974, 1134200, 30982, '<td valign="top">I like the bold, electric colors.</td>', 'I like the bold, electric colors.', '2014-11-04 23:19:39.000000', NULL, 1),
(7279975, 1134163, 30982, '<td valign="top">Nice catch, wonderfully understated in processing.</td>', 'Nice catch, wonderfully understated in processing.', '2014-11-04 23:19:57.000000', NULL, 1),
(7279976, 1134155, 30982, '<td valign="top">Great contrast - has a late 60s industrial feel to it.</td>', 'Great contrast - has a late 60s industrial feel to it.', '2014-11-04 23:20:16.000000', NULL, 1),
(7279977, 1134219, 30982, '<td valign="top">Great sense of scale - nice isolation from the masses beyond.</td>', 'Great sense of scale - nice isolation from the masses beyond.', '2014-11-04 23:20:43.000000', NULL, 1),
(7279978, 1134170, 30982, '<td valign="top">Gorgeous morning light!!</td>', 'Gorgeous morning light!!', '2014-11-04 23:20:58.000000', NULL, 1),
(7279979, 1134167, 30982, '<td valign="top">I do not know Ned, but I think this is a phenominal portrait.  If this IS Ned, then he''s a man of mystery with a great sense of humor.</td>', 'I do not know Ned, but I think this is a phenominal portrait.  If this IS Ned, then he''s a man of mystery with a great sense of humor.', '2014-11-04 23:21:42.000000', NULL, 1),
(7279980, 1132253, 30982, '<td valign="top">A non-abstract abstraction, if that makes sense.  Nicely seen, well presented.</td>', 'A non-abstract abstraction, if that makes sense.  Nicely seen, well presented.', '2014-11-04 23:22:10.000000', NULL, 1),
(7279981, 1134145, 30982, '<td valign="top">I will come back to see where this is.</td>', 'I will come back to see where this is.', '2014-11-04 23:22:31.000000', NULL, 1),
(7279982, 1134147, 30982, '<td valign="top">And no one is happy here, not even the guy heading the other way.  Makes one wonder where the joy in the world has gone.  All grays and blacks, no glimpse of daylight or color.</td>', 'And no one is happy here, not even the guy heading the other way.  Makes one wonder where the joy in the world has gone.  All grays and blacks, no glimpse of daylight or color.', '2014-11-04 23:23:03.000000', NULL, 1),
