(7280622, 1134213, 13077, '<td valign="top">Must be Cuba? Nicely captured and well composed slice of life here. Excellent exposure and processing.</td>', 'Must be Cuba? Nicely captured and well composed slice of life here. Excellent exposure and processing.', '2014-11-05 20:38:06.000000', NULL, 1),
(7280623, 1134139, 13077, '<td valign="top">Very nice detail and I like the soft tones.</td>', 'Very nice detail and I like the soft tones.', '2014-11-05 20:38:17.000000', NULL, 1),
(7280624, 1134002, 13077, '<td valign="top">Very cool surreal processing on this one, and a fascinating scene.</td>', 'Very cool surreal processing on this one, and a fascinating scene.', '2014-11-05 20:38:31.000000', NULL, 1),
(7280625, 1134025, 13077, '<td valign="top">Super cool. Very moody and contrasty, looks like it could be from a drama or mystery movie.</td>', 'Super cool. Very moody and contrasty, looks like it could be from a drama or mystery movie.', '2014-11-05 20:39:23.000000', NULL, 1),
