(7280628, 1134152, 13077, '<td valign="top">I like it - intriguing.</td>', 'I like it - intriguing.', '2014-11-05 20:41:22.000000', NULL, 1),
(7280629, 1134196, 13077, '<td valign="top">Maybe. Unless they looked more like birds like some people seem to think.<br/>Either way, very cool reptile and excellent job capturing the details and colors in its skin.</td>', 'Maybe. Unless they looked more like birds like some people seem to think.Either way, very cool reptile and excellent job capturing the details and colors in its skin.', '2014-11-05 20:42:16.000000', NULL, 1),
(7280630, 1133284, 13077, '<td valign="top">I like it. Has a postcard vibe.</td>', 'I like it. Has a postcard vibe.', '2014-11-05 20:42:33.000000', NULL, 1),
