(7280634, 1134195, 13077, '<td valign="top">The light is good, but the bird sort of gets lost in the leaves behind it.</td>', 'The light is good, but the bird sort of gets lost in the leaves behind it.', '2014-11-05 20:46:21.000000', NULL, 1),
(7280635, 1134041, 13077, '<td valign="top">I like the processing here - good detail in the trees as well as the background. I like all the various textures and colors in the scene.</td>', 'I like the processing here - good detail in the trees as well as the background. I like all the various textures and colors in the scene.', '2014-11-05 20:47:02.000000', NULL, 1),
