(7280643, 1134273, 13077, '<td valign="top">I like the title, and well composed and exposed for the whole scene.</td>', 'I like the title, and well composed and exposed for the whole scene.', '2014-11-05 20:51:04.000000', NULL, 1),
(7280644, 1133748, 13077, '<td valign="top">Nice - I like the composition, and how the sharp rocks visually interact with the soft rest of the scene.</td>', 'Nice - I like the composition, and how the sharp rocks visually interact with the soft rest of the scene.', '2014-11-05 20:51:49.000000', NULL, 1),
