(7280692, 1133847, 13077, '<td valign="top">Very nice scene with the fog and the soft light bringing out the colors well. Good composition too.</td>', 'Very nice scene with the fog and the soft light bringing out the colors well. Good composition too.', '2014-11-05 21:37:16.000000', NULL, 1),
(7280693, 1134145, 13077, '<td valign="top">Nicely done. I seem to remember seeing photos of this place before. Very cool composition and great job keeping detail in the whole thing.</td>', 'Nicely done. I seem to remember seeing photos of this place before. Very cool composition and great job keeping detail in the whole thing.', '2014-11-05 21:38:07.000000', NULL, 1),
(7280694, 1133652, 13077, '<td valign="top">Very up-close-and-personal shot here, for sure. I wonder if including all of the antlers would have looked better?</td>', 'Very up-close-and-personal shot here, for sure. I wonder if including all of the antlers would have looked better?', '2014-11-05 21:38:40.000000', NULL, 1),
(7280695, 1131908, 13077, '<td valign="top">Very dramatic. I like how the lower half almost mirrors the upper half but it puts its own unique spin on things. Beautiful photo overall.</td>', 'Very dramatic. I like how the lower half almost mirrors the upper half but it puts its own unique spin on things. Beautiful photo overall.', '2014-11-05 21:39:33.000000', NULL, 1),
(7280697, 1134216, 13077, '<td valign="top">Nice. Interesting how half of her face is in shadow, I like it.</td>', 'Nice. Interesting how half of her face is in shadow, I like it.', '2014-11-05 21:39:50.000000', NULL, 1),
(7280698, 1132439, 13077, '<td valign="top">I like how the bridge really stands out as the only man-made object here.</td>', 'I like how the bridge really stands out as the only man-made object here.', '2014-11-05 21:40:13.000000', NULL, 1),
(7280700, 1132083, 13077, '<td valign="top">Very nice. The ''land'' portion of the photo does so much with so little, and I think it wouldn''t work as well if it took up more of the frame. The sky is beautifully soft and dreamy too.</td>', 'Very nice. The ''land'' portion of the photo does so much with so little, and I think it wouldn''t work as well if it took up more of the frame. The sky is beautifully soft and dreamy too.', '2014-11-05 21:41:06.000000', NULL, 1),
(7280701, 1131925, 13077, '<td valign="top">Super colorful, almost ominously red.</td>', 'Super colorful, almost ominously red.', '2014-11-05 21:41:39.000000', NULL, 1),
(7280702, 1132187, 13077, '<td valign="top">Brrr! I like the little bit of motion in the clouds.</td>', 'Brrr! I like the little bit of motion in the clouds.', '2014-11-05 21:41:56.000000', NULL, 1),
(7280703, 1134115, 13077, '<td valign="top">Good illustration of these kind of rays.</td>', 'Good illustration of these kind of rays.', '2014-11-05 21:42:15.000000', NULL, 1),
(7280706, 1134001, 13077, '<td valign="top">Nice street portrait - well composed with good amount of soft background and nice light. Well-placed focus as well, and good job showing all the elements in his clothing and face that make him a character.</td>', 'Nice street portrait - well composed with good amount of soft background and nice light. Well-placed focus as well, and good job showing all the elements in his clothing and face that make him a character.', '2014-11-05 21:43:40.000000', NULL, 1),
(7280707, 1133857, 13077, '<td valign="top">Creepy.</td>', 'Creepy.', '2014-11-05 21:43:49.000000', NULL, 1),
