(7282182, 1134167, 114285, '<td valign="top">A striking portrait indeed.</td>', 'A striking portrait indeed.', '2014-11-08 06:49:09.000000', NULL, 0),
(7282183, 1133370, 32641, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Kobba:</b></div><hr/><i> Guessing that some sort of gradient was applied in post.  Either way something just is off, can''t really put my finger on it.  Wish I could. </i></td></tr></table> <br/>No gradient applied, but the conditions were extra ordinary because of air pollution from the volcanic eruption in Holuhraun in North Iceland at that time. This is shot with 70-200 mm f/2.8  with a x2 extender @400mm.</td>', 'Originally posted by Kobba: Guessing that some sort of gradient was applied in post.  Either way something just is off, can''t really put my finger on it.  Wish I could.  No gradient applied, but the conditions were extra ordinary because of air pollution from the volcanic eruption in Holuhraun in North Iceland at that time. This is shot with 70-200 mm f/2.8  with a x2 extender @400mm.', '2014-11-08 07:14:22.000000', NULL, 0),
(7282184, 1134117, 97225, '<td valign="top">Congratulations on the red. Love it!</td>', 'Congratulations on the red. Love it!', '2014-11-08 07:24:36.000000', NULL, 0),
